+      ctx.lineWidth = b.owner === 'player' ? 1.3 : 1.1;
+      ctx.beginPath();
+      ctx.moveTo(b.x - dx * len * 0.55, b.y - dy * len * 0.55);
+      ctx.lineTo(b.x, b.y);
