+    const dy = aim.y - p.y;
+    const d = Math.hypot(dx, dy) || 1;
+    const hit = g.map.raycast(p.x, p.y, p.x + (dx / d) * Math.min(d, 420), p.y + (dy / d) * Math.min(d, 420), 420);
+    const endX = hit ? hit.x : p.x + (dx / d) * Math.min(d, 420);
+    const endY = hit ? hit.y : p.y + (dy / d) * Math.min(d, 420);
