  getObjective() {
    if (!this.player || this.skirmish) {
      return {
        kicker: 'SURVIVAL PROTOCOL',
        text: `SURVIVE WAVE ${this.wave}`,
        sub: `${this.aliveCount()} HOSTILES // BEST W${this.save.stats.bestSurvival}`,
        live: this.wavePending,
