      kicker: 'PRIMARY OBJECTIVE',
      text: 'ELIMINATE HOSTILES',
      sub: `${this.run?.kills || 0} / ${total} // INTEL ${this.run?.intel || 0} / ${this.mission?.intel || 0}`,
