// Application entry point: wires the simulation, renderer and interface together.

import { Game } from './game.js';
import { Renderer } from './render.js';
import { UI } from './ui.js';

function boot() {
  const game = new Game();
  game.renderer = new Renderer(game);
  game.ui = new UI(game);
  game.init();
  window.game = game;
  window.addEventListener('error', (event) => {
    console.error('[vanguard] runtime error', event.error || event.message);
  });
  window.addEventListener('unhandledrejection', (event) => {
    console.error('[vanguard] unhandled rejection', event.reason);
  });
  document.body.classList.add('ready');
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', boot, { once: true });
} else {
  boot();
}

// Offline shell for Vanguard Ballistics. Cache-first for the app, network-first for nothing.
const CACHE = 'vanguard-ballistics-v1';
const ASSETS = [
  './',
  './index.html',
  './manifest.webmanifest',
  './css/style.css',
  './js/main.js',
  './js/game.js',
  './js/render.js',
  './js/ui.js',
  './js/maps.js',
  './js/content.js',
  './js/util.js',
  './js/audio.js',
  './assets/icon.svg',
  './assets/icon-192.png',
  './assets/icon-512.png',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((cache) => cache.addAll(ASSETS))
      .then(() => self.skipWaiting())
      .catch(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET' || !request.url.startsWith(self.location.origin)) return;
  event.respondWith(
    caches.match(request).then((cached) => {
      if (cached) return cached;
      return fetch(request)
        .then((response) => {
          if (!response || response.status !== 200 || response.type === 'opaque') return response;
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put(request, copy)).catch(() => {});
          return response;
        })
        .catch(() => caches.match('./index.html'));
    }),
  );
});

// Minimal CDP driver for visual + runtime checks.
import fs from 'node:fs';

const PORT = process.env.CDP_PORT || 9222;
const BASE = `http://127.0.0.1:${PORT}`;

async function http(path, method = 'GET') {
  const res = await fetch(BASE + path, { method });
  return res.json();
}

export async function openPage(url) {
  const target = await http(`/json/new?${encodeURIComponent(url)}`, 'PUT');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  let id = 0;
  const pending = new Map();
  const events = [];
  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const { res, rej } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) rej(new Error(JSON.stringify(msg.error)));
      else res(msg.result);
    } else if (msg.method) {
      events.push(msg);
    }
  };
  const send = (method, params = {}) => new Promise((res, rej) => {
    const mid = ++id;
    pending.set(mid, { res, rej });
    ws.send(JSON.stringify({ id: mid, method, params }));
  });
  const logs = [];
  const onEvent = (fn) => { events.push = (...args) => { fn(...args); EventTarget.prototype; }; };
  const drain = () => {
    const out = events.splice(0);
    for (const e of out) {
      if (e.method === 'Runtime.consoleAPICalled') {
        logs.push({
          level: e.params.type,
          text: e.params.args.map((a) => a.value ?? a.description ?? a.unserializableValue ?? '').join(' '),
        });
      } else if (e.method === 'Runtime.exceptionThrown') {
        const d = e.params.exceptionDetails;
        logs.push({ level: 'exception', text: `${d.text} ${d.exception?.description || ''} @${d.url || ''}:${d.lineNumber}` });
      } else if (e.method === 'Log.entryAdded') {
        logs.push({ level: e.params.entry.level, text: e.params.entry.text });
      }
    }
    return out;
  };
  await send('Runtime.enable');
  await send('Log.enable');
  await send('Page.enable');
  const evaluate = async (expression, awaitPromise = false) => {
    const r = await send('Runtime.evaluate', { expression, awaitPromise, returnByValue: true, userGesture: true });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text);
    return r.result?.value;
  };
  const wait = (ms) => new Promise((res) => setTimeout(res, ms));
  const screenshot = async (file, quality = 60) => {
    const r = await send('Page.captureScreenshot', { format: 'jpeg', quality });
    fs.writeFileSync(file, Buffer.from(r.data, 'base64'));
    return file;
  };
  const click = async (selector) => {
    const box = await evaluate(`(() => { const el = document.querySelector(${JSON.stringify(selector)}); if (!el) return null; const r = el.getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + r.height / 2 }; })()`);
    if (!box) throw new Error('no element ' + selector);
    for (const type of ['mousePressed', 'mouseReleased']) {
      await send('Input.dispatchMouseEvent', { type, x: box.x, y: box.y, button: 'left', clickCount: 1 });
    }
    return box;
  };
  const close = async () => {
    try { await send('Page.close'); } catch { /* ignore */ }
    ws.close();
  };
  return { send, evaluate, wait, screenshot, click, drain, logs, close, target };
}

export async function connectBlank() {
  const list = await http('/json/list');
  const page = list.find((t) => t.type === 'page');
  return openPage(page.url === 'about:blank' ? 'about:blank' : page.url);
}

