import { openPage } from './cdp.mjs';

const page = await openPage('http://localhost:8123/index.html');
await page.wait(2200);
await page.evaluate('window.game.startMission(0)');
await page.wait(1200);
console.log('state', await page.evaluate('window.game.state'));
console.log('enemies', await page.evaluate('window.game.enemies.length'), 'spawns', await page.evaluate('window.game.map.enemySpawns.map(s=>s.type+":"+Math.round(s.x)+","+Math.round(s.y)).join(" | ")'));
// Teleport near first enemy and reset camera
await page.evaluate(`(() => { const g=window.game; const e=g.enemies[0]; g.player.x=e.x+170; g.player.y=e.y; g.player.angle=Math.PI; g.renderer.resetCamera(); })()`);
await page.wait(300);
await page.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: 720, y: 450 });
await page.wait(2500);
const info = await page.evaluate(`(() => { const g=window.game; return {
  hp: g.player.hp, armor: g.player.armor,
  enemyStates: g.enemies.map(e => e.type + ':' + e.state + ':' + Math.round(e.hp) + ':see=' + e.canSee),
  bullets: g.bullets.length, enemyBullets: g.bullets.filter(b=>b.owner==='enemy').length,
  shots: g.run.shots, kills: g.run.kills, alert: g.enemies[0].alert,
}; })()`);
console.log(JSON.stringify(info, null, 1));
await page.screenshot('/tmp/opencode/shot-10-combat.jpg', 55);
// Kill all enemies via player damage to test objectives/extraction
await page.evaluate(`(() => { const g=window.game; for (const e of g.enemies) if(!e.dead) g.damageEnemy(e, 9999, 0, true, e.x, e.y, true); })()`);
await page.wait(600);
console.log('after kill state', await page.evaluate('window.game.state'), 'extractionActive', await page.evaluate('window.game.extractionActive'), 'kills', await page.evaluate('window.game.run.kills'));
await page.evaluate(`(() => { const g=window.game; g.player.x=g.map.extraction.x; g.player.y=g.map.extraction.y; })()`);
await page.wait(600);
console.log('after exfil state', await page.evaluate('window.game.state'), 'panel', await page.evaluate('window.game.ui.panelKind'), 'results', JSON.stringify(await page.evaluate('window.game.pendingResults')));
await page.screenshot('/tmp/opencode/shot-11-results.jpg', 55);
// Continue to next mission
await page.evaluate('window.game.continueAfterResults()');
await page.wait(1400);
console.log('next state', await page.evaluate('window.game.state'), 'missionIndex', await page.evaluate('window.game.missionIndex'), 'unlocked', await page.evaluate('window.game.save.unlocked'));
await page.screenshot('/tmp/opencode/shot-12-op2.jpg', 55);
console.log('logs', JSON.stringify(page.drain().filter(e=>e.method&&e.method.startsWith('Runtime')||e.method==='Log.entryAdded')));
await page.close();

