  const state = await page.evaluate('game.state');
  await page.evaluate(`(() => { const g=game; for (const e of g.enemies) if(!e.dead) g.damageEnemy(e, 9999, 0, true, e.x, e.y, true); })()`);
  await page.wait(400);
  const ext = await page.evaluate('game.extractionActive');
  await page.evaluate(`(() => { const g=game; g.player.x=g.map.extraction.x; g.player.y=g.map.extraction.y; })()`);
  await page.wait(600);
  const res = await page.evaluate(`({state:game.state, panel:game.ui.panelKind, success:game.pendingResults?.success, index:game.pendingResults?.mission?.index, unlocked:game.save.unlocked, completed:game.save.completed.length, credits:game.save.credits})`);
  console.log('MISSION', i, state, 'ext', ext, JSON.stringify(res));
  await page.evaluate('game.continueAfterResults()');
  await page.wait(1000);
}

console.log('AFTER CAMPAIGN', JSON.stringify(await page.evaluate(`({state:game.state, all:game.allComplete(), unlocked:game.save.unlocked, completed:game.save.completed, owned:game.save.ownedWeapons, settings:game.save.settings})`)));
await page.evaluate('game.returnToMenu()');
await page.wait(500);
console.log('MENU', await page.evaluate(`({deploy:document.getElementById('btn-deploy-card').textContent.trim(), skirmishCard:!!document.querySelector('.skirmish-card'), missionCard:document.getElementById('mission-name')?.textContent})`));
await page.screenshot('/tmp/opencode/shot-60-menu-complete.jpg', 55);
await page.evaluate('game.startSkirmish()');
await page.wait(1200);
console.log('SKIRMISH START', await page.evaluate(`({state:game.state, skirmish:game.skirmish, wave:game.wave, enemies:game.enemies.length})`));
await page.evaluate('game.abortMission()');
await page.wait(600);

// Armory purchases + upgrade effects
await page.evaluate(`game.save.credits = 99999; game.persist(); game.ui.openPanel('armory');`);
await page.wait(500);
console.log('ARMORY BEFORE', await page.evaluate(`({owned:game.save.ownedWeapons, upgrades:game.save.upgrades, weapon:game.save.loadout.primary})`));
await page.evaluate(`game.buyWeapon('sentinel')`);
await page.evaluate(`game.buyUpgrade('mag'); game.buyUpgrade('armor'); game.buyUpgrade('pouch');`);
await page.wait(300);
console.log('ARMORY AFTER', await page.evaluate(`({owned:game.save.ownedWeapons, upgrades:game.save.upgrades, weapon:game.save.loadout.primary, credits:game.save.credits})`));
await page.evaluate('game.startMission(0)');
await page.wait(1000);
console.log('LOADOUT', await page.evaluate(`({weapon:game.player.weapon.name, mag:game.player.weapon.mag, maxArmor:game.player.maxArmor, grenades:game.player.grenades})`));
await page.evaluate('game.abortMission()');
await page.wait(500);

// settings persistence
await page.evaluate('game.save.settings.shake=false; game.save.settings.aimAssist=false; game.persist();');
await page.send('Page.reload');
await page.wait(2200);
console.log('PERSIST', await page.evaluate(`({credits:game.save.credits, unlocked:game.save.unlocked, completed:game.save.completed.length, shake:game.save.settings.shake, weapon:game.save.loadout.primary, upgrades:game.save.upgrades})`));
console.log('ERRORS', JSON.stringify(page.drain().filter((e) => e.level === 'exception' || e.level === 'error')));
await page.close();

